samples.scenes/courtyard/scene:
- {
  kind scene
  id courtyard
  size {
    width 48
    height 36
    layers 3
  }
  tiles tiles
  background {
    colour 0 0 0
    music "media/audio/courtyard.ogg"
  }
  start 96 96 1
  regions {
    - {
      id north-wall
      kind solid
      layer 1
      closed #true
      points {
        - 0 0
        - 192 0
        - 192 32
        - 0 32
      }
    }
    - {
      id patrol
      kind waypoint
      layer 1
      closed #false
      points {
        - 48 64
        - 144 64
        - 144 112
      }
    }
  }
  triggers {
    - {
      id to-hall
      layer 1
      area {
        - 160 96
        - 192 96
        - 192 128
        - 160 128
      }
      run {
        inline "send(\"hall\", 32, 96, 1);"
      }
      activation {
        onKey #false
      }
    }
  }
  placements {
    - {
      id gatekeeper-1
      actor gatekeeper
      at 64 96 1
      whilePresent {
        inline "\"Halt! Who goes there?\" asked the gatekeeper.\nmwin(\"Halt! Who goes there?\");\nitemPath(\"source\", tkMV_WAYPOINT_LINK, \"patrol\", 0);\n// backslash \\ and a quoted \"word\" and a delimiter-like \"\"\"triple\"\"\" plus |pipe|\n// single 'quotes', a tab\there, and C:\\Games\\P

